#!/usr/bin/env python3
"""Run from project root: python3 fix_vos.py"""
import base64, os, sys
if not os.path.exists("app"): sys.exit(1)
FILES = {
    "lib/vos/types.ts": "",
    "lib/vos/assetRegistry.ts": "",
    "lib/vos/commandRegistry.ts": "",
    "lib/vos/commands.ts": "",
    "components/vos/VerificationTerminal.tsx": "",
    "app/terminal/page.tsx": "",
}
for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")
print("""
ABRAXAS VERIFICATION OS — INSTALLED

New architecture:
  lib/vos/types.ts             Core type definitions
  lib/vos/assetRegistry.ts     Asset database (extensible)
  lib/vos/commandRegistry.ts   Command registry + parser
  lib/vos/commands.ts          All command handlers
  components/vos/              Terminal UI component

Available commands:
  help, status, list, inspect, verify
  show provenance, show custody, show collateral
  show risk, show valuation, show events, clear

Reserved (phase 2):
  attest, underwrite, finance, vault, oracle, audit

Adding a new command requires editing ONE file (lib/vos/commands.ts).
The terminal UI never needs changes.

Run:
  npm run build
  git add -A
  git commit -m "feat: Verification OS — command terminal, registry architecture, intelligence reports"
  git push origin main

Then navigate to /terminal → TERMINAL tab → COMMAND TERMINAL
Try: inspect AAS-1
""")
